<?php use Namira\{CallUI,CallExport};view('calls-assets');$status=CallExport::status($job); ?>
<div class="heading"><h2>آماده‌سازی خروجی فراخوان</h2><a class="outline" href="<?= e(url('admin',['tab'=>'submissions'])) ?>">بازگشت به آثار</a></div><section class="panel" data-call-export-job data-job="<?= $job['id'] ?>"><p>حالت داوری: <?= $status['anonymous']?'بدون مشخصات ارسال‌کننده و صاحب اثر':'با مشخصات افراد؛ خصوصی' ?></p><progress max="<?= max(1,$status['total']) ?>" value="<?= $status['processed'] ?>" data-call-export-progress></progress><p data-call-export-state><?= fa($status['processed']).' از '.fa($status['total']) ?> اثر پردازش شده است. <?= $status['state']==='ready'?'خروجی آماده است.':'این صفحه را برای ادامه ساخت باز نگه دارید.' ?></p><p class="notice notice-error" data-call-export-error <?= !$status['error']?'hidden':'' ?>><?= e($status['error']) ?></p><form method="post" data-call-export-step><?= CallUI::csrfForm('call2-export-step',['id'=>$job['id']]) ?><button class="primary" <?= $status['state']==='ready'?'hidden':'' ?>>ادامه ساخت / تلاش مجدد</button></form><div data-call-export-downloads><?php if($status['state']==='ready'):foreach($status['parts'] as $part): ?><article class="call-export-part"><b>بسته <?= fa($part['number']) ?> · <?= fa($part['codes']) ?> کد اثر</b><a class="outline" href="<?= e(url('call-export-download',['id'=>$job['id'],'part'=>$part['number'],'kind'=>'xlsx'])) ?>">دریافت Excel</a><?php if($part['zip']): ?><a class="primary" href="<?= e(url('call-export-download',['id'=>$job['id'],'part'=>$part['number'],'kind'=>'zip'])) ?>">دریافت ZIP همراه Excel</a><?php endif ?></article><?php endforeach;endif ?></div><p class="hint">خروجی‌های بزرگ چندبسته‌ای ساخته می‌شوند. کد رهگیری در Excel و پوشه فایل‌ها یکسان است؛ همه بسته‌ها را دریافت کنید. لینک‌ها خصوصی و وابسته به دسترسی حساب شما هستند.</p><script type="application/json" data-call-export-status><?= json_encode($status,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script></section>